(function(){
 const nav=document.getElementById('league-hq-tabs');if(!nav)return;
 let folderURL='';
 const render=hjRenderHQTabs;
 function decorate(){
  nav.querySelectorAll('[data-hq-tab]').forEach((button,index)=>{
   if(button.querySelector('.hq-folder-art'))return;
   const label=document.createElement('span');label.className='hq-folder-label';label.textContent=button.textContent;
   const art=document.createElement('img');art.className='hq-folder-art';art.alt='';art.draggable=false;art.setAttribute('aria-hidden','true');
   if(folderURL)art.src=folderURL;else art.hidden=true;
   button.replaceChildren(art,label);button.style.setProperty('--folder-layer',String(6-index));
  });
 }
 function fitLabels(){
  nav.querySelectorAll('.hq-folder-label').forEach(label=>{
   label.style.fontSize='14px';
   if(label.clientWidth&&label.scrollWidth>label.clientWidth)label.style.fontSize=(14*label.clientWidth/label.scrollWidth-.25)+'px';
  });
 }
 hjRenderHQTabs=function(){render.apply(this,arguments);decorate();requestAnimationFrame(fitLabels)};
 if(document.fonts)document.fonts.ready.then(fitLabels);
 if(window.ResizeObserver)new ResizeObserver(fitLabels).observe(nav);
 // Color-key the neutral preview matte from the supplied raster at runtime.
 // The artwork itself determines every contour; no vector geometry is involved.
 const source=new Image();
 source.onload=()=>{
  const canvas=document.createElement('canvas');canvas.width=source.naturalWidth;canvas.height=source.naturalHeight;
  const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0);
  const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),d=pixels.data;
  for(let i=0;i<d.length;i+=4){const warmth=d[i]-d[i+2];d[i+3]=Math.round(255*Math.max(0,Math.min(1,(warmth-7)/14)))}
  ctx.putImageData(pixels,0,0);folderURL=canvas.toDataURL('image/png');
  nav.querySelectorAll('.hq-folder-art').forEach(art=>{art.src=folderURL;art.hidden=false});
 };
 source.src='[embedded-image]';
 hjRenderHQTabs();window.HJ_BUILD='v84-folder-headroom-motion';
})();

/* Shared player rows: an independent, vertically centered score column. */
function hjPlayerRowV3(entry,week,right=false,roster=false){
 if(!entry)return '<div class="hj-player-v3 is-empty">—</div>';
 const p=hjPlayer(entry),id=p?.id||entry?.playerId||'',name=p?.fullName||p?.displayName||p?.name||'Player',position=hjPlayerPosition(entry),rank=hjPlayerRank(entry),team=hjPlayerTeam(entry),photo=hjPlayerPhoto(entry),pair=hjProjectionPair(entry,week),actual=hjPlayerActualScore(entry,week),state=hjPlayerGameState(team),hasActual=Number.isFinite(actual)&&(state!=='pre'||Math.abs(actual)>.0001),status=String(entry?.injuryStatus||p?.injuryStatus||'').replace(/^NORMAL$/i,''),slot=roster?hjPlayerSlot(entry):'';
 return `<button class="hj-player-v3 pc-player-trigger${right?' is-right':''}${roster?' hj-roster-player':''}" type="button" data-game-in-progress="${state==='in'&&Number(week)===Number(hjCurrentWeek(HJ_LEAGUE_STATE.data))?'true':'false'}" ${ffnPlayerDataAttrs({id,name,team,position,photo})} aria-label="Open ${esc(name)} player profile"><span class="hj-v3-avatar">${photo?`<img src="${esc(photo)}" alt="" loading="lazy" onerror="ffnImageFallback(this)">`:`<span>${esc(hjInitials(name))}</span>`}</span><span class="hj-v3-identity"><span class="hj-v3-name" title="${esc(name)}">${esc(roster?name:hjLineupDisplayName(name,position))}</span><span class="hj-v3-meta">${esc(team)} · <span class="hj-v3-rank">${esc(position)}${rank||''}</span>${status?` <span class="hj-v3-injury">${esc(status)}</span>`:''}</span></span>${hjGameContextHTML({id,name,team,position},week,entry)}<span class="hj-v3-score"><strong ${hasActual?hjPerformanceAttrs(actual,pair.espn):''}>${hasActual?pcFpts(actual):'—'}</strong><span class="hj-v3-projection">${hjProjectionFlipHTML(pair.espn,pair.vegas,`${roster?'roster':'lineup'}:${week}:${id}`)}</span></span></button>`;
}
hjLineupPlayerHTML=(entry,week,right=false)=>hjPlayerRowV3(entry,week,right,false);
const hjPriorRosterRowV3=hjPlayerHTML;
hjPlayerHTML=function(entry,week,season=HJ_LEAGUE_SEASON){return Number(season)===Number(HJ_LEAGUE_SEASON)?hjPlayerRowV3(entry,week,false,true):hjPriorRosterRowV3(entry,week,season)};
(function(){
 const previewOpen=new Map(),scopeIds=new WeakMap();let sequence=0,queued=false;
 const scopeSelector='#hq-panel-matchups,#league-sync-content,#hq-panel-free-agents,#hq-panel-strength,#hq-panel-recap,#hq-panel-activity,.manager-hq-roster,.profile-live-roster,.pc-modal,.manager-modal-back';
 function sectionId(root){if(root.id)return root.id;if(!scopeIds.has(root))scopeIds.set(root,'projection-section-'+(++sequence));return scopeIds.get(root)}
 function sections(){
  const roots=new Set();
  document.querySelectorAll('.hj-proj-flip').forEach(chip=>{const root=chip.closest(scopeSelector)||chip.closest('section');if(root&&!chip.closest('.pc-modal,.depth-row'))roots.add(root)});
  roots.forEach(root=>{
   const id=sectionId(root);root.dataset.hjProjectionSection=id;
   let button=[...root.querySelectorAll('[data-hj-section-projections]')].find(b=>b.dataset.hjSectionProjections===id);
   if(!button){button=document.createElement('button');button.type='button';button.className='hj-section-projections';button.dataset.hjSectionProjections=id;
    const host=root.querySelector('.league-roster-head,.hq-module-head,.hq40-controls,.hq49-controls,.profile-live-roster-head,.profile-section-title,.pc-profile-nav,.manager-hq-roster-toolbar,.league-roster-group-head')||root;
    host.append(button);
   }
   hjProjectionPrepareSection(root,id);
   const label='E/V';if(button.textContent!==label)button.textContent=label;
   button.title='Switch projections in this section';button.setAttribute('aria-label',`Switch this section to ${hjProjectionSectionSource(id)==='vegas'?'ESPN':'Vegas'} projections`);
  });
 }
 function previews(){document.querySelectorAll('#hq-panel-matchups .hq-matchup').forEach(card=>{
  if(card.querySelector('.hj-matchup-preview'))return;
  const edge=card.querySelector('.hq-edge-grid'),toolbar=card.querySelector('.hq-lineup-toolbar'),head=card.querySelector('.hj-lineup-v2-head');if(!edge||!toolbar||!head)return;
  const key=card.dataset.hqMatchupKey,actions=document.createElement('div');actions.className='hj-matchup-actions';
  const tray=document.createElement('details');tray.className='hj-matchup-preview';tray.dataset.matchupKey=key;tray.open=previewOpen.get(key)||false;
  const summary=document.createElement('summary');summary.textContent='Matchup Preview';tray.append(summary);
  const body=document.createElement('div');body.className='hj-matchup-preview-body';tray.insertBefore(body,summary);
  edge.before(actions);actions.append(tray);
  toolbar.querySelector('.hq-lineup-toolbar-copy')?.remove();body.append(edge,toolbar,head);
  tray.addEventListener('toggle',()=>{previewOpen.set(key,tray.open);schedule()});
 });}
 const canvas=document.createElement('canvas'),measure=canvas.getContext('2d');
 function fitRows(){
  const containers=new Set();document.querySelectorAll('.hj-player-v3').forEach(p=>containers.add(p.closest('.hj-lineup-v2,.league-roster-groups,.profile-live-roster')||p.parentElement));
  containers.forEach(root=>{
   if(!root.getClientRects().length)return;
   const narrow=root.clientWidth<980;
   root.querySelectorAll('.hj-player-v3').forEach(p=>{
    if(narrow){if(p.dataset.narrowInfo!=='true')p.dataset.narrowInfo='true'}
    else if(p.hasAttribute('data-narrow-info'))p.removeAttribute('data-narrow-info');
   });
  });
 }
 function displayDST(){
  document.querySelectorAll('option:not([value])').forEach(o=>{if(o.textContent.includes('D/ST'))o.setAttribute('value',o.textContent)});
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement?.closest('script,style,textarea,input')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  let n;while(n=walker.nextNode())if(n.nodeValue.includes('D/ST'))n.nodeValue=n.nodeValue.replaceAll('D/ST','DST');
  document.querySelectorAll('[aria-label*="D/ST"],[title*="D/ST"]').forEach(el=>{for(const a of ['aria-label','title'])if(el.hasAttribute(a)&&el.getAttribute(a).includes('D/ST'))el.setAttribute(a,el.getAttribute(a).replaceAll('D/ST','DST'))});
 }
 function folders(){
  const nav=document.getElementById('league-hq-tabs');if(!nav)return;
  if(!nav.parentElement.classList.contains('hj-folder-dock')){const dock=document.createElement('div');dock.className='hj-folder-dock';nav.before(dock);dock.append(nav);}
  const height=nav.parentElement.getBoundingClientRect().height||86;
  const top=document.querySelector('body > nav')?.getBoundingClientRect().height||0;
  if(document.documentElement.style.getPropertyValue('--hj-file-tabs-height')!==height+'px')document.documentElement.style.setProperty('--hj-file-tabs-height',height+'px');
  if(document.documentElement.style.getPropertyValue('--hj-main-nav-height')!==top+'px')document.documentElement.style.setProperty('--hj-main-nav-height',top+'px');
 }
 function fonts(){
  const roots=document.querySelectorAll('#hq-panel-free-agents,.manager-hq-roster,.profile-live-roster,.league-roster-groups,.league-roster-head,#hq-panel-matchups .hq-module-head,#hq-panel-matchups .hq-matchup-head,#hq-panel-matchups .hq-matchup-summary,#hq-panel-matchups .hq-match-win,#hq-panel-matchups .hq-matchup-switcher');
  roots.forEach(root=>[root,...root.querySelectorAll('*')].forEach(el=>{
   if(el.closest('.hq-match-team-score.is-actual,.league-roster-lineup-head-total,.league-roster-total,.league-matchup-team b.is-actual'))return;
   if(el.style.getPropertyValue('font-family')!=='var(--sans)')el.style.setProperty('font-family','var(--sans)','important');
  }));
 }
 function update(){queued=false;previews();sections();folders();fitRows();fonts();displayDST();}
 function schedule(){if(!queued){queued=true;requestAnimationFrame(update)}}
 window.addEventListener('resize',schedule);
 document.fonts?.ready.then(schedule);
 window.addEventListener('click',event=>{
  const b=event.target.closest?.('[data-hj-section-projections]');if(!b)return;
  event.preventDefault();event.stopImmediatePropagation();const id=b.dataset.hjSectionProjections;
  const root=[...document.querySelectorAll('[data-hj-projection-section]')].find(r=>r.dataset.hjProjectionSection===id);if(root){hjProjectionToggleSection(root,id);schedule()}
 },true);
 new MutationObserver(records=>{if(records.some(r=>r.addedNodes.length||r.removedNodes.length))schedule()}).observe(document.body,{childList:true,subtree:true});
 schedule();
 if(HJ_LEAGUE_STATE?.data){hjRenderMatchupCenter();if(typeof hjRenderLeague==='function')hjRenderLeague()}
})();

(function(){
 const nav=document.getElementById('league-hq-tabs');if(!nav)return;
 let queued=0;
 // Preserve the source's paper surfaces. A vertical slice through the
 // undecorated tab neck gives the labels clearance above all paper edges.
 const bands=[[0,107,-6,26],[107,190,26,70],[190,683,70,168.6]];
 function drawStrip(ctx,img,srcX,srcW,x,width){
  for(const [sy,ey,dy,de] of bands)ctx.drawImage(img,srcX,sy,srcW,ey-sy,x,dy,width,de-dy);
 }
 function tiles(ctx,img,srcX,srcW,left,right,scale){
  if(right<=left)return;
  const tw=srcW*scale;ctx.save();ctx.beginPath();ctx.rect(left,-10,right-left,180);ctx.clip();
  for(let x=left,i=0;x<right;x+=tw,i++){
   ctx.save();ctx.translate(x,0);if(i%2){ctx.translate(tw,0);ctx.scale(-1,1)}
   drawStrip(ctx,img,srcX,srcW,0,tw);ctx.restore();
  }ctx.restore();
 }
 function render(){
  queued=0;const dock=nav.closest('.hj-folder-dock');if(!dock)return;
  const bounds=nav.getBoundingClientRect();if(!bounds.width)return;
  const buttons=[...nav.querySelectorAll('.hq-tab')],last=buttons[buttons.length-1];
  const railWidth=Math.max(nav.clientWidth,last?last.offsetLeft+last.offsetWidth+200:nav.clientWidth);
  const nr={width:railWidth};
  const ratio=window.devicePixelRatio||1;
  nav.querySelectorAll('.hq-tab').forEach((button,index)=>{
   const source=button.querySelector('.hq-folder-art');if(!source?.complete||!source.naturalWidth)return;
   let canvas=button.querySelector('.hj-folder-layer');
   if(!canvas){canvas=document.createElement('canvas');canvas.className='hj-folder-layer';canvas.setAttribute('aria-hidden','true');button.prepend(canvas)}
   const r=button.getBoundingClientRect();
   const left=button.offsetLeft,scale=(r.width+215)/2048;
   const paintKey=[railWidth,r.width,left,ratio].join(':');
   if(canvas._paintKey===paintKey&&canvas._paintSource===source.src)return;
   const artX=left-15,joinLeft=artX+140*scale,joinRight=artX+1100*scale;
   const width=Math.round(nr.width*ratio),height=Math.round(180*ratio);
   if(canvas.width!==width)canvas.width=width;if(canvas.height!==height)canvas.height=height;
   const xOffset=-left+'px';if(canvas.style.left!==xOffset)canvas.style.left=xOffset;
   const cssWidth=nr.width+'px';if(canvas.style.width!==cssWidth)canvas.style.width=cssWidth;
   const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,-10,nr.width,190);
   // Flat wings are sampled at their native scale and mirrored, never
   // stretched. Their upper edges match the corresponding source shoulder.
   tiles(ctx,source,100,40,0,Math.min(nr.width,Math.max(0,joinLeft+4)),scale);
   tiles(ctx,source,1100,700,Math.max(0,joinRight-4),nr.width,scale);
   // Keep the tab and all three original paper edges together in one image.
   drawStrip(ctx,source,140,960,joinLeft,960*scale);
   // Derive a clean shadow from the actual opaque paper contour. The
   // original keyed image has translucent matte pixels outside the paper;
   // filtering the whole button shadows that matte instead of the tab edge.
   const shadowKey=[width,height,left,r.width].join(':');
   if(canvas._paperShadowKey!==shadowKey||canvas._paperSource!==source.src){
    const mask=document.createElement('canvas');mask.width=width;mask.height=height;
    const m=mask.getContext('2d',{willReadFrequently:true});m.drawImage(canvas,0,0);
    const pixels=m.getImageData(0,0,width,height);
    for(let p=0;p<pixels.data.length;p+=4){
     pixels.data[p]=pixels.data[p+1]=pixels.data[p+2]=0;
     pixels.data[p+3]=pixels.data[p+3]>=220?255:0;
    }
    m.putImageData(pixels,0,0);
    const shadow=document.createElement('canvas');shadow.width=width;shadow.height=height;
    const sh=shadow.getContext('2d');sh.shadowColor='rgba(65,45,23,.48)';
    sh.shadowBlur=5*ratio;sh.shadowOffsetY=-1.5*ratio;sh.shadowOffsetX=1*ratio;
    sh.drawImage(mask,0,0);sh.shadowColor='transparent';
    sh.globalCompositeOperation='destination-out';sh.drawImage(mask,0,0);
    canvas._paperShadow=shadow;canvas._paperShadowKey=shadowKey;canvas._paperSource=source.src;
   }
   ctx.save();ctx.globalCompositeOperation='destination-over';
   ctx.drawImage(canvas._paperShadow,0,0,width,height,0,0,nr.width,180);ctx.restore();
   // Match the panel at its boundary, below the visible paper layers.
   // Only four pixels blend; no broad overlay conceals the folder stack.
   const localBottom=nav.clientHeight;
   const fade=ctx.createLinearGradient(0,localBottom-4,0,localBottom);
   fade.addColorStop(0,'rgba(249,237,215,0)');fade.addColorStop(1,'#f9edd7');
   ctx.fillStyle=fade;ctx.fillRect(0,localBottom-4,nr.width,5);
   ctx.fillStyle='#f9edd7';ctx.fillRect(0,localBottom,nr.width,180-localBottom);
   button.classList.add('hj-layer-ready');canvas._paintKey=paintKey;canvas._paintSource=source.src;
  });

 }
 function schedule(){if(!queued)queued=requestAnimationFrame(render)}
 nav.addEventListener('load',e=>{if(e.target.classList.contains('hq-folder-art'))schedule()},true);

 window.addEventListener('resize',schedule);document.fonts?.ready.then(schedule);
 new ResizeObserver(schedule).observe(nav);
 new MutationObserver(records=>{if(records.some(r=>r.type==='childList'||r.attributeName==='aria-selected'||r.target.classList?.contains('hq-folder-art')))schedule()}).observe(nav,{childList:true,subtree:true,attributes:true,attributeFilter:['src','aria-selected']});
 schedule();
})();

(function(){
 const root='#hq-panel-matchups',ready=new WeakSet();
 const pages=deck=>Array.from(deck.children).filter(el=>el.matches('.hq-matchup'));
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function choose(deck,index){
  const card=pages(deck)[index];if(!card)return;
  const key=card.dataset.hqMatchupKey;HJ_HQ_STATE.matchupFocusKey=key;
  document.querySelectorAll(root+' [data-hq-matchup-jump]').forEach(b=>{
   const active=b.dataset.hqMatchupJump===key;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));
  });hjCenterMatchupJumpChipV32(key);
 }
 function go(deck,index,animate){
  if(!pages(deck)[index])return;
  deck.scrollTo({left:index*deck.clientWidth,behavior:animate&&!reduced()?'smooth':'instant'});
 }
 function install(){
  const deck=document.querySelector(root+' .hq-matchup-list');if(!deck||ready.has(deck)||!deck.clientWidth)return;
  ready.add(deck);deck.tabIndex=0;deck.setAttribute('aria-label','Matchups. Scroll left or right.');
  let timer;
  const settle=()=>{
   const index=Math.max(0,Math.min(pages(deck).length-1,Math.round(deck.scrollLeft/deck.clientWidth)));
   if(pages(deck)[index]?.dataset.hqMatchupKey!==HJ_HQ_STATE.matchupFocusKey)choose(deck,index);
  };
  if('onscrollend' in deck)deck.addEventListener('scrollend',settle);
  else deck.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(settle,180)},{passive:true});
  deck.addEventListener('keydown',event=>{
   if(event.target!==deck||!['ArrowLeft','ArrowRight'].includes(event.key))return;
   event.preventDefault();go(deck,Math.round(deck.scrollLeft/deck.clientWidth)+(event.key==='ArrowRight'?1:-1),true);
  });
  go(deck,Math.max(0,pages(deck).findIndex(c=>c.dataset.hqMatchupKey===HJ_HQ_STATE.matchupFocusKey)),false);
  let width=deck.clientWidth;
  const observer=new ResizeObserver(()=>{
   if(!deck.isConnected){observer.disconnect();return}
   if(deck.clientWidth<=0||Math.abs(width-deck.clientWidth)<1)return;
   width=deck.clientWidth;go(deck,Math.max(0,pages(deck).findIndex(c=>c.dataset.hqMatchupKey===HJ_HQ_STATE.matchupFocusKey)),false);
  });observer.observe(deck);
 }
 window.addEventListener('click',event=>{
  const b=event.target.closest(root+' [data-hq-matchup-jump]');if(!b)return;
  const deck=document.querySelector(root+' .hq-matchup-list');if(!deck)return;
  const index=pages(deck).findIndex(c=>c.dataset.hqMatchupKey===b.dataset.hqMatchupJump);if(index<0)return;
  event.preventDefault();event.stopImmediatePropagation();choose(deck,index);go(deck,index,true);
 },true);
 let pending=false;
 new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;install()})}}).observe(document.querySelector('#league-hq'),{childList:true,subtree:true});
 window.addEventListener('resize',install);install();
})();

(function(){
 const railSelector='#hq-panel-matchups .hq-matchup-switcher,#league-sync-content .league-team-rail';
 function reveal(rail){
  if(!rail.clientWidth||!rail.getClientRects().length)return;
  const card=rail.querySelector('.hq-matchup-jump.active,.league-team-tab.active,[aria-pressed="true"]');
  if(!card)return;
  const box=rail.getBoundingClientRect(),item=card.getBoundingClientRect(),pad=5;
  const left=box.left+rail.clientLeft+pad,right=box.left+rail.clientLeft+rail.clientWidth-pad;
  let delta=0;
  if(item.width>right-left)delta=item.left-left;
  else if(item.left<left)delta=item.left-left;
  else if(item.right>right)delta=item.right-right;
  if(Math.abs(delta)>.5)rail.scrollTo({left:Math.max(0,Math.min(rail.scrollWidth-rail.clientWidth,rail.scrollLeft+delta)),behavior:'instant'});
 }
 // Use rail-relative bounds: offsetLeft can refer to an ancestor outside the rail.
 hjCenterMatchupJumpChipV32=function(){
  schedule();
 };
 const seen=new WeakSet(),lastSelection=new WeakMap();let pending=false;
 const resize=new ResizeObserver(()=>schedule());
 function apply(){
  pending=false;
  document.querySelectorAll(railSelector).forEach(rail=>{
   if(!seen.has(rail)){seen.add(rail);resize.observe(rail)}
   const active=rail.querySelector('.hq-matchup-jump.active,.league-team-tab.active,[aria-pressed="true"]');
   if(!active||!rail.clientWidth||!rail.getClientRects().length)return;
   const key=active.dataset.hqMatchupJump||active.dataset.leagueTeam||'';
   const previous=lastSelection.get(rail);
   if(!previous||previous.key!==key||previous.card!==active){
    lastSelection.set(rail,{key,card:active});reveal(rail);
   }
  });
 }
 function schedule(){if(!pending){pending=true;requestAnimationFrame(apply)}}
 new MutationObserver(records=>{
  if(records.some(r=>r.type==='childList'||r.target.matches?.('.hq-tab-panel,.hq-tab,.league-team-tab,.hq-matchup-jump')))schedule();
 }).observe(document.querySelector('#league-hq'),{childList:true,subtree:true,attributes:true,attributeFilter:['class','aria-pressed','hidden','style']});
 window.addEventListener('resize',schedule);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule()});
 schedule();
})();
